const features=[{icon:Gamepad2,title:'Minecraft, your way.',copy:'A space for Minecraft Java instances, mod loaders, mods and modpacks. Keep each adventure in its own local folder.',tag:'MINECRAFT JAVA',wide:true},{icon:Layers3,title:'Your services, together.',copy:'A dashboard and services catalogue with a useful guest mode. One central Solara account for protected services.',tag:'THE ECOSYSTEM'},{icon:Server,title:'Your servers. One place.',copy:'View permitted hosting resources, open the game panel and manage supported server operations.',tag:'HOSTING'},{icon:Monitor,title:'Run a local server.',copy:'Set up a local Java server on your computer, accept the EULA and follow its console.',tag:'LOCAL SERVERS'},{icon:Globe,title:'Give your server a name.',copy:'Request a subdomain for a verified public endpoint. DNS requires a reachable server and does not bypass CGNAT.',tag:'PUBLIC HOSTING'},{icon:Download,title:'Follow every download.',copy:'A shared home for real downloads, installation progress and verified release updates.',tag:'DOWNLOADS'},{icon:Activity,title:'Let your friends know.',copy:'Optional Discord activity for Solara and your local Minecraft state, without sharing private account details.',tag:'DISCORD'}];
const questions=[['Do I need a Solara account?','Public dashboard browsing, public listings and public installer downloads do not require sign-in. Protected hosting, subdomain and beta operations use your central Solara account. Local Minecraft uses a separate licensed game account.'],['Where does my Microsoft account data go?','Microsoft/Minecraft authentication is handled directly on your device with official services. Microsoft passwords never enter a Solara form, and Minecraft tokens are not sent to the Solara API. Local credentials require operating-system secure storage.'],['Is Minecraft included?','Solara is a launcher, not a game licence. A valid Minecraft Java entitlement is required for full play. Solara sign-in does not replace Minecraft ownership verification.'],['Will a subdomain make my home server reachable?','No. DNS exposes your chosen public IP/port and gives it a name. You still need a reachable endpoint, firewall configuration and any required port forwarding. CGNAT may require a separately selected connectivity service; the Solara VPS is not a gameplay relay.'],['How are updates verified?','The download is called solaralauncher.exe. After installation, Solara is designed to download and apply signed updates automatically when no game, local server or download is active. Unpublished, withdrawn or unverified artifacts are not offered as downloadable releases.'],['Can I build the source myself?','The desktop application and publishable website frontend are intended to be public source. Independently implemented Solara backend code remains private. Restricted API access requires an approved public client ID and user/developer entitlements; a shared application secret is never embedded.'],['What is available today?','This website is a development implementation. The first planned public build is V-0.0.01. Download availability below reflects real verified release metadata, and remains unavailable until a Windows installer has been built, checked and published.'],['Where can I get help?','Use Solara’s existing support destination. Registration and account recovery happen through the central account site. Integration status and release information come from the single main Solara API.']];
onMounted(()=>{void refreshPublic();timer=setInterval(()=>void refreshPublic(),60000)});onUnmounted(()=>{if(timer)clearInterval(timer)});
function selectTheme(value:string){preview.value=value==='auto'?null:value;preferences.value.theme=value==='none'?'neutral':'auto';savePreferences()}
async function copyChecksum(r:any){await navigator.clipboard.writeText(r.sha256);copied.value=r.buildId;setTimeout(()=>copied.value='',2500)}
